{
  "schemaVersion": "0.2",
  "slug": "file-input",
  "name": "FileInput",
  "status": "experimental",
  "purpose": "Allows a user to select a file from their device.",
  "scenarios": [
    "Upload a profile picture",
    "Attach a document",
    "Import a CSV file"
  ],
  "props": {
    "label": {
      "type": "string",
      "required": true,
      "description": "Input label."
    },
    "accept": {
      "type": "string",
      "required": false,
      "description": "Accepted MIME types or extensions."
    },
    "onChange": {
      "type": "event",
      "required": true,
      "description": "Called when files are selected."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "empty",
      "description": "No file selected."
    },
    {
      "name": "selected",
      "description": "One or more files selected."
    }
  ],
  "composition": {
    "allowedParents": [
      "form",
      "page"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for drag-and-drop-only upload.",
    "Do not read file contents without consent."
  ],
  "a11y": {
    "role": "button",
    "keyboard": [
      "Tab focuses",
      "Enter/Space opens file picker"
    ],
    "focus": "Input is focusable.",
    "labeling": "Label identifies the input purpose.",
    "wcag": [
      "2.1.1",
      "3.3.2"
    ]
  },
  "responsive": {
    "strategy": "Native input with styled label.",
    "breakpoints": {
      "compact": "Full width.",
      "medium": "Inline or block.",
      "large": "Inline or block."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "file-input",
    "states": [
      "empty",
      "selected"
    ],
    "intents": [
      "upload-file"
    ]
  }
}

import { useState } from 'react'
import './styles.css'

export interface FileInputProps {
  label: string
  accept?: string
  onChange: (files: FileList | null) => void
  className?: string
}

export function FileInput({ label, accept, onChange, className }: FileInputProps) {
  const [names, setNames] = useState<string[]>([])
  const classes = ['cu-file-input', className].filter(Boolean).join(' ')
  return (
    <label className={classes} data-ai-role="file-input" data-ai-intent="upload-file" data-ai-state={names.length > 0 ? 'selected' : 'empty'}>
      <span className="cu-file-input__label">{label}</span>
      <input
        accept={accept}
        className="cu-file-input__input"
        onChange={(event) => {
          const files = event.currentTarget.files
          setNames(files ? Array.from(files).map((f) => f.name) : [])
          onChange(files)
        }}
        type="file"
      />
      {names.length > 0 ? <span className="cu-file-input__names">{names.join(', ')}</span> : null}
    </label>
  )
}

.cu-file-input {
  display: inline-flex;
  flex-direction: column;
  gap: var(--cu-space-1);
  cursor: pointer;
}

.cu-file-input__label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--cu-color-fg-default);
}

.cu-file-input__input {
  inline-size: 100%;
  color: var(--cu-color-fg-default);
}

.cu-file-input__names {
  font-size: 0.875rem;
  color: var(--cu-color-fg-default);
  opacity: 0.8;
}
